import openpyxl

def search_queue(path, names):
    wb = openpyxl.load_workbook(path, data_only=True)
    for sheet in wb.sheetnames:
        ws = wb[sheet]
        headers = None
        for row in ws.iter_rows(values_only=True):
            if not headers:
                if any('Project' in str(c) or 'ID' in str(c) or 'Application' in str(c) for c in row if c):
                    headers = [str(c).strip() if c else '' for c in row]
                    # print('Headers in', sheet, ':', headers)
                continue
            row_str = ' '.join(str(c) for c in row if c)
            for name in names:
                if name.lower() in row_str.lower():
                    print(f'[{path} - {sheet}] MATCH {name}:')
                    for h, v in zip(headers, row):
                        if v is not None:
                            print(f'  {h}: {v}')

names = ['Cravenwood', 'Darnwick', 'Holcott', 'Lockmere', 'Marden', 'Tresbay']
search_queue('Queue/2025-07-14_Active_Queue_Report.xlsx', names)
