import os, docx, openpyxl, fitz

sites = ['cravenwood', 'darnwick', 'holcott', 'lockmere', 'marden', 'tresbay']

def check_text(p, text):
    lower = text.lower()
    for s in sites:
        if s in lower:
            print(f'[{s.upper()}] found in: {p}')

for root, dirs, files in os.walk('.'):
    for f in files:
        p = os.path.join(root, f)
        if p.startswith('./.'): continue
        ext = os.path.splitext(f)[1].lower()
        try:
            if ext == '.pdf':
                doc = fitz.open(p)
                t = ' '.join(page.get_text() for page in doc)
                check_text(p, t)
            elif ext == '.docx':
                d = docx.Document(p)
                t = ' '.join(para.text for para in d.paragraphs)
                check_text(p, t)
            elif ext == '.xlsx':
                wb = openpyxl.load_workbook(p, data_only=True)
                t = ''
                for sheet in wb.sheetnames:
                    ws = wb[sheet]
                    for r in ws.iter_rows(values_only=True):
                        t += ' ' + ' '.join(str(c) for c in r if c)
                check_text(p, t)
            elif ext in ['.eml', '.txt', '.md']:
                with open(p, 'r', errors='ignore') as fp:
                    check_text(p, fp.read())
        except Exception as e:
            pass
"

